var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`THADDEUS_PRYDWEN_NULL_NULL`,text:{KOREA:`하핫, 이빨 빠진 승냥이가 이런 멋진 제안을 받을 줄이야. 당분간 근처에서 수상한 녀석들이 얼쩡거려도 신경 꺼주시게. 해묵은 일들은 내가 직접 청산할 테니까.`,JPN:`ははっ。牙の抜けた狼が、こんないい提案を持ちかけられるとは。当分の間は、この辺に怪しいやつらがいても気にしないでくれ。古い因縁は俺が直接片付けておくから。`,ENG:`Hah hah. Who knew I'd get such a great offer in my declining years? Pay no mind even if you see some suspicious people around the company. I have some old scores to settle with them.`,TWN:`哈哈，牙齒都快掉光的老豺狗也能收到這麼棒的提案。就算這陣子有可疑的傢伙在附近亂晃，你也不用操心。過去的事情，我會直接清算乾淨的。`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`THADDEUS_PRYDWEN_NULL_NULL`,face:`UNIT_LAUGH`,hologram:!1},R:null}}}];export{e as default};